INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Projekte immer langfristig angelegt?', 2, '[{"text": "Nein", "correct": true, "because": "Projekte können kurz- oder langfristig sein"}, {"text": "Ja", "correct": false, "because": "Dauer variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein zentrales Merkmal eines Projekts?', 3, '[{"text": "Einmaligkeit", "correct": true, "because": "Projekte sind einzigartig"}, {"text": "Routinemäßigkeit", "correct": false, "because": "Nicht typisch"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Strukturierte Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren ein Projekt?', 5, '[{"text": "Zeitliche Begrenzung", "correct": true, "because": "Projekte haben Start und Ende"}, {"text": "Zielorientierung", "correct": true, "because": "Verfolgen spezifische Ziele"}, {"text": "Unbegrenzte Ressourcen", "correct": false, "because": "Ressourcen begrenzt"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projekte haben ein festes Ziel. b) Sie sind immer wiederkehrend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist einmalig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition von Projektmerkmalen?', 4, '[{"text": "Zeitplan", "correct": false, "because": "Definiert Ablauf"}, {"text": "Ressourcenbedarf", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Merkmale"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Projekt immer interdisziplinär sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch ein Fachbereich sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal unterscheidet ein Projekt von Routineaufgaben?', 3, '[{"text": "Einmaligkeit", "correct": true, "because": "Projekte sind einzigartig"}, {"text": "Regelmäßigkeit", "correct": false, "because": "Routineaufgaben sind wiederkehrend"}, {"text": "Manuelle Planung", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen ein Projekt komplex?', 5, '[{"text": "Interdisziplinarität", "correct": true, "because": "Verschiedene Fachbereiche"}, {"text": "Ressourcenknappheit", "correct": true, "because": "Erhöht Planungsaufwand"}, {"text": "Einheitliche Aufgaben", "correct": false, "because": "Vereinfacht Projekt"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Projekte haben ein festes Ende. b) Sie benötigen keine Planung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Definition von Projektmerkmalen?', 4, '[{"text": "Ziele", "correct": false, "because": "Definiert Projekt"}, {"text": "Zeitrahmen", "correct": false, "because": "Begrenzt Dauer"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Irrelevant für Merkmale"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben Projekte immer ein festes Budget?', 2, '[{"text": "Nein", "correct": true, "because": "Budget kann flexibel sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Komplexität eines Projekts?', 4, '[{"text": "Anzahl der Beteiligten", "correct": true, "because": "Erhöht Koordination"}, {"text": "Unklare Ziele", "correct": true, "because": "Erschwert Planung"}, {"text": "Büroausstattung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Projekte immer risikofrei sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Projekte haben Risiken"}, {"text": "Ja", "correct": false, "because": "Risiken typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse von Projektmerkmalen?', 3, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Leiten Projekt"}, {"text": "Maximale Dauer", "correct": false, "because": "Realismus wichtiger"}, {"text": "Manuelle Planung", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projekte sind zeitlich begrenzt. b) Sie sind immer einfach zu planen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann komplex sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein klar definiertes Projekt?', 5, '[{"text": "Bessere Planbarkeit", "correct": true, "because": "Klarheit erleichtert"}, {"text": "Erhöhte Erfolgswahrscheinlichkeit", "correct": true, "because": "Ziele erreichbar"}, {"text": "Unbegrenzte Dauer", "correct": false, "because": "Begrenzung nötig"}, {"text": "Einheitliche Aufgaben", "correct": false, "because": "Vielfalt typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Projektmerkmalen unwichtig?', 3, '[{"text": "Ressourcenbedarf", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Zeitrahmen", "correct": false, "because": "Definiert Dauer"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Projektfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Projekte immer ein festes Team haben?', 2, '[{"text": "Nein", "correct": true, "because": "Teams können wechseln"}, {"text": "Ja", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Projekt immer einzigartig?', 3, '[{"text": "Ja", "correct": true, "because": "Einmaligkeit definiert Projekt"}, {"text": "Nein", "correct": false, "because": "Wiederholung untypisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Projektmerkmalen?', 4, '[{"text": "Entwicklung einer neuen Software", "correct": true, "because": "Einmalig, zeitlich begrenzt"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Projekt"}, {"text": "Tägliche Wartung", "correct": false, "because": "Routineaufgabe"}]');
